# content_anem.py — 30호 ANEM Maturitas Original article 본문(수치는 numbers_anem에서만, 2026-11-16).
#  인용 = [@key] 또는 [@web:...]; 번호 (n) 첫 인용 순. 단독 저자 → 1인칭 금지. 결과 절 해석 금지, 고찰 통계 수치 없음. 제목 쌍점 금지, 시리즈 제목 틀 반복 금지.
#  Maturitas: 본문 2,000-3,000단어, 참고 ≤30, 구조 초록 ≤250(Objectives·Study design·Main outcome measures·Results·Conclusions), 키워드 1-6, Highlights 3-5(≤85자).
from numbers_anem import load, ROB, RS, OLD, DM, NUT, UPT, HYP
N = load()
def ci(v, src=None):
    r = (src or N["main"])[v]; return f"RR {r['IRR']:.3f}; 95% CrI {r['lo']:.3f}–{r['hi']:.3f}"
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {t[1]:.3f}–{t[2]:.3f}"
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["nco"][(o, v)]
SC = lambda s, v: N["sens_main"][s][v]
WI = lambda v, w: N["win_irr"][(v, w)]
EN = {"전라남도": "South Jeolla", "경상북도": "North Gyeongsang", "경상남도": "South Gyeongsang", "충청남도": "South Chungcheong", "전라북도": "North Jeolla",
      "강원도": "Gangwon", "부산시": "Busan", "충청북도": "North Chungcheong", "대구시": "Daegu", "경기도": "Gyeonggi", "서울시": "Seoul", "인천시": "Incheon",
      "광주시": "Gwangju", "울산시": "Ulsan", "대전시": "Daejeon", "세종시": "Sejong", "제주도": "Jeju"}
def sidos(d, n):
    l = [f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + " and " + l[-1]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
TITLE = "Is more anaemia flagged at national health screening in Korean districts where older adults live alone?"
RUNNING = "Geography of screen-detected anaemia"
assert ":" not in TITLE and "229" not in TITLE and "228" not in TITLE and "standardi" not in TITLE.lower() and len(RUNNING) <= 40
KEYWORDS = ["Anaemia", "Mass screening", "Living alone", "Aged", "Diabetes mellitus", "Spatiotemporal analysis"]
assert 1 <= len(KEYWORDS) <= 6
NOVELTY = {"new": "This study maps anaemia flagged at routine national health screening across 228 harmonised Korean districts, using 14 years and over 200 million screening records.",
           "central": "Age- and sex-standardised anaemia was concentrated in the south of Korea and was higher in districts with more older adults living alone and more attendees with diagnosed diabetes, whereas physical activity indicators showed no credible association.",
           "clinical": "Districts with many older adults living alone or with diabetes may be priorities for examining how abnormal haemoglobin results from screening are followed up."}
assert all(t.count(".") == 1 and t.endswith(".") for t in NOVELTY.values())
NHYP = N["n_hyp"]; EXP_CHANCE = 0.05 * NHYP; assert NHYP == 13
SUP = {"methods": 1, "covariates": 2, "checks": 3, "maps": 4, "windows": 5, "specs": 6, "posthoc": 7, "strobe": 8}
def sup(k): return f"Supplementary Appendix S{SUP[k]}"
_pc = lambda v: f"{100*N['mv'][v]['cred_frac']:.0f}%"
ALT = N["retention"]
NULLV = ["multicultural_marriage_share", "current_smoking_rate", "high_risk_drinking_rate", "walking_practice_rate", "moderate_pa_rate", "im_specialists_per_100k", "tertiary_educated_share"]
REV = ["basic_livelihood_rate", "ext__total_fertility_rate"]
BEST = min(KH, key=lambda a: N["s43_waic"][a])
nat = N["nat_pos_y"]; NR = N["rate"]

ABSTRACT = {
 "Objectives": "To describe the district geography of anaemia flagged at national health screening in Korea and its associations with district characteristics, including the share of older adults living alone.",
 "Study design": f"Ecological panel study of {N['exam_total']/1e6:.0f} million general health screening records from {N['n_districts']} districts, 2011–2024, analysed with negative binomial Bayesian spatiotemporal models and {NHYP} district characteristics, with negative-control exposures among the robustness checks.",
 "Main outcome measures": "Sex- and age-standardised ratios of records flagged with suspected anaemia, and rate ratios per standard deviation of each district characteristic.",
 "Results": f"Of all records, {N['cases_total']/1e6:.1f} million were flagged; national positivity peaked at {max(nat.values()):.1f}% in 2015 and was {nat[2024]:.1f}% in 2024. Standardised ratios clustered strongly, with hot spots in the south and cold spots in the capital region. Ratios were higher with a larger share of older adults living alone (rate ratio per standard deviation {M[OLD]['IRR']:.2f}; 95% credible interval {M[OLD]['lo']:.2f}–{M[OLD]['hi']:.2f}) and of attendees with diagnosed diabetes ({M[DM]['IRR']:.2f}; {M[DM]['lo']:.2f}–{M[DM]['hi']:.2f}), both persisting, smaller, in all four space–time interaction models. Screening uptake was positively associated ({M[UPT]['IRR']:.2f}) but credible in only two interaction models. A small inverse association with nutrition-label literacy ({M[NUT]['IRR']:.2f}) was no larger than those of two negative-control exposures. Walking and moderate-or-vigorous activity showed no credible association.",
 "Conclusions": "Screen-detected anaemia in Korea follows a stable southern geography associated, at district level, with older adults living alone and, less robustly, diabetes. Residual confounding cannot be excluded; these findings generate hypotheses for studies of diet, iron status and causes of anaemia in older adults living alone.",
}

INTRO = [
 f"Anaemia affected almost a quarter of the world's population in 2021, dietary iron deficiency was its leading cause, and its burden varies widely by age, sex and place [@gbd2023prevalence]. In the United States, prevalence exceeded 20% at age 85 years or older, and nutrient deficiency, chronic inflammation or renal disease, and unexplained anaemia each accounted for about one-third of anaemia in older people [@guralnik2004prevalence]; renal insufficiency, inflammation and an age-related decline in erythropoietin production contribute [@stauder2018anemia]. In older people, anaemia is associated with a decline in physical performance [@penninx2003anemia].",
 f"In a Korean national survey, older adults with anaemia more often lived alone, received social assistance or had diabetes or chronic renal failure [@chueh2020high]; in Korean adults diabetes was associated with anaemia [@kim2021association], and in older adults nutritional anaemia was associated with lower nutrient intake [@park2019comparison]. Iron deficiency remains common worldwide [@pasricha2021iron], and thalassaemia carriage has been found in young people of multiethnic background in Korea [@lee2019increased]. These studies describe individuals; they cannot show where anaemia accumulates within a country.",
 f"Korea's National Health Insurance Service screens tens of millions of adults [@seong2017cohort], and the national statistics portal reports each year the number of screening records flagged as suspected anaemia in every district [@web:kosis2026screening]. District-level clustering of anaemia has been shown among rural men in India [@singh2024district], but, to the author's knowledge, routine haemoglobin screening of a national adult population has not been used to map where anaemia accumulates and which area characteristics accompany it. Area characteristics plausibly matter: living alone is associated with malnutrition risk in older people [@besoramoreno2020social], food insecurity with micronutrient deficiency and anaemia [@lopes2023food], and nutrition-label reading with healthier micronutrient intake [@kim2014association], whereas smoking raises haemoglobin and can mask anaemia [@nordenberg1990effect].",
 f"This study used 14 years of national screening results to ask where in Korea anaemia is flagged more often than expected for the sex and age of attendees, how stable that geography is, and which district characteristics of deprivation, household composition, nutrition-label literacy, chronic disease, lifestyle and access are associated with it.",
]

METHODS = [
("Design, outcome and population",
 f"This ecological panel study used annual district statistics of the general health screening programme of the National Health Insurance Service [@seong2017cohort]. For each district and year, the number of screening records with a recorded judgement and the number flagged as suspected anaemia under the programme's haemoglobin criteria were taken from the national statistics portal, as were national numbers by sex and age group [@web:kosis2026screening]. Counts are screening records, not unique individuals; people may attend in several years. The flag reflects the programme's own haemoglobin criterion, which is not published with the statistics; it is therefore a marker of screen-detected low haemoglobin, not of nutritional anaemia, and cannot be compared directly with survey-defined anaemia. Districts were harmonised to 2024 boundaries. Sejong, reported separately in only 1 of 14 years, was excluded, leaving {N['n_districts']} districts and {N['n_rows']:,} district-years for 2011–2024 ({sup('methods')})."),
("Sex and age standardisation",
 f"Expected numbers flagged were obtained by indirect standardisation [@inskip1983methods]. National positivity in each year, sex and age group (19 years or younger, 5-year groups from 20–24 to 80–84 years, and 85 years or older) was applied to the estimated age structure of each district's attendees, derived from the resident population by sex and 5-year age group [@web:mois2026population] and national uptake by sex and age, and rescaled to the observed number of attendees of each sex. The standardised anaemia ratio is the observed over the expected number. Using the national positivity of the same year accounts for nationwide changes in positivity, including the change between 2016 and 2017 reported in the Results, but not for changes in selection or measurement that differ between districts."),
("District characteristics",
 f"District characteristics and their expected directions were fixed before any covariate model was fitted, on the basis of the epidemiology of anaemia. Deprivation, household composition and nutrition-label literacy: basic livelihood security receipt (+) [@chueh2020high; @lopes2023food], tertiary education (−), nutrition-label literacy (−) [@kim2014association] and the share of households of older adults living alone (+) [@chueh2020high; @besoramoreno2020social]. Women and childbearing: the share of marriages involving a foreign spouse (+) [@lee2019increased] and the total fertility rate (+) [@pasricha2021iron]. Chronic disease: the share of attendees with diagnosed diabetes (+) [@thomas2003unrecognized; @kim2021association; @stauffer2014prevalence]. Lifestyle and physical activity from the Community Health Survey: current smoking (−) [@nordenberg1990effect], high-risk drinking (+), and walking and moderate-or-vigorous physical activity (−, hypothesised through better general health; population evidence is scarce). Access and selection: internal medicine specialists per 100,000 population (−) and screening uptake (−, with healthier people attending where uptake is high). Five controls were forced into every model: urban population share, physicians per 1,000 population, sex ratio, fiscal autonomy and the share aged 80 years or older. Covariates were standardised to 1 standard deviation (SD). The share of older adults living alone was observed from 2015; its 2011–2014 values (912 district-years) were filled with district means, so within-district variation in this characteristic arises only from 2015. Tertiary education was observed only in the 2015 and 2020 censuses and was interpolated or held at the nearest census value; other gaps were filled within districts ({sup('covariates')}; checks in {sup('checks')})."),
("Statistical analysis",
 f"The likelihood (Poisson or negative binomial) was chosen by the lower widely applicable information criterion (WAIC) of the forced-controls model. Models had an offset of log expected numbers, a Besag–York–Mollié 2 (BYM2) district effect with penalised-complexity priors [@riebler2016intuitive] and random-walk and independent year effects, and were fitted by integrated nested Laplace approximation [@rue2009approximate] in R 4.6.0. Rate ratios (RRs) per 1 SD are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1. RRs are mutually adjusted ecological associations, not individual or causal effects [@morgenstern1995ecologic]. No multiplicity adjustment was applied, and associations were interpreted as exploratory, in light of their size and robustness. Following the multiverse approach [@steegen2016increasing], the model was refitted with 200 random covariate subsets; a covariate was subset-stable if credible in at least 75% of the subsets containing it, with the same sign in at least 95%. Residual hot and cold spots had a posterior probability greater than 0.95 or less than 0.05 that the residual spatial RR exceeded 1, for the whole period and for two windows separated by the 2016–2017 change in national positivity (2011–2016 and 2017–2024)."),
("Sensitivity analyses",
 f"Knorr-Held type I–IV space–time interactions were added [@knorrheld2000bayesian]; subset-stable covariates were split into district means and within-district deviations [@bell2015explaining]; the model was refitted in each window and with covariate-by-window interactions in a single model sharing one spatial effect and set of controls across windows; and expected numbers were recomputed from the resident population instead of attendees, which changes the estimand from positivity among attendees to flagged records per resident. Further specifications varied the likelihood, priors, neighbourhoods, controls, lags, left-out provinces or years and filled values ({sup('specs')}). Treated gastric cancer and infectious disease (district counts of people treated, from the same statistics portal) served as comparison outcomes and hit-and-run accidents, fires and household waste recycling as negative-control exposures [@lipsitch2010negative]; E-values indicated the strength of unmeasured district-level confounding needed to explain each association [@vanderweele2017sensitivity]. After the results were seen, associations against the expected direction were examined post hoc with the between–within decomposition, rank correlations of district means and correlations among covariates ({sup('posthoc')})."),
("Ethics and reporting",
 "The study used only published aggregate statistics and involved no individual data; the Institutional Review Board of Hongik University approved the study on 4 November 2025 (7002340-202511-HR-012) and its continuing review on 3 November 2026 (7002340-202611-HR-040) and waived informed consent, and the study was conducted in accordance with the Declaration of Helsinki. The study follows the STROBE statement (" + sup("strobe") + ")."),
]

_e = lambda k: tuple(N['negctl'][k][x] for x in ('IRR', 'lo', 'hi'))
RESULTS = [
("Screening and positivity",
 f"Over 2011–2024, {N['exam_total']/1e6:.1f} million screening records included {N['cases_total']:,} flagged with suspected anaemia (Table 1). National positivity was {nat[2011]:.2f}% in 2011, peaked at {max(nat.values()):.2f}% in 2015 and fell to {nat[2024]:.2f}% in 2024. Positivity rose steeply with age in men, to {NR[(2024, '남자', '85+')]:.1f}% at 85 years or older in 2024, whereas women had a peak at 40–44 and 45–49 years ({NR[(2024, '여자', '40-44')]:.1f}% and {NR[(2024, '여자', '45-49')]:.1f}% in 2024), a trough at 55–64 years and a second rise thereafter (Fig. 1). Between 2016 and 2017, positivity at 55 years or older fell by {abs(N['drop1617']['남자']):.0f}% in men and {abs(N['drop1617']['여자']):.0f}% in women."),
("Spatial pattern",
 f"Moran's I of observed log ratios was {N['moran_pooled']:.2f} pooled over years and {N['moran_year_min']:.2f}–{N['moran_year_max']:.2f} annually; the BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f}–{N['phi'][2]:.2f}). Residual RRs ranged from {N['rr_min']:.2f} to {N['rr_max']:.2f}, with {N['n_hot']} hot spots, mainly in {sidos(N['hot_by_sido'], 3)}, and {N['n_cold']} cold spots, mainly in {sidos(N['cold_by_sido'], 3)} (Fig. 2A). Of the hot spots, {N['hot_gun']} were rural counties. In both windows, {N['hot_all_windows']} districts were hot spots and {N['cold_all_windows']} cold spots (Fig. 2B), and district rankings were stable across years (Kendall's W {N['kendall_W']:.2f}) ({sup('maps')})."),
("District characteristics",
 f"The negative binomial likelihood was selected (WAIC {N['waic_nb']:,.1f} vs {N['waic_pois']:,.1f}). Adding the {NHYP} characteristics changed WAIC from {N['waic_forced']:,.1f} to {N['waic_main']:,.1f}; residual Moran's I was {N['moran_resid']:.2f} (P={N['moran_resid_p']:.2f}). Six characteristics were credible, and four were subset-stable (Table 2). Standardised ratios were higher with a larger share of older adults living alone ({ci(OLD)}) and of attendees with diagnosed diabetes ({ci(DM)}), and lower with higher nutrition-label literacy ({ci(NUT)}). Against the expected direction, they were higher with higher screening uptake ({ci(UPT)}) and lower with more basic livelihood security receipt ({ci('basic_livelihood_rate')}) and a higher total fertility rate ({ci('ext__total_fertility_rate')}); the last two were credible in only {_pc('basic_livelihood_rate')} and {_pc('ext__total_fertility_rate')} of subsets. Walking ({ci('walking_practice_rate')}), moderate-or-vigorous activity ({ci('moderate_pa_rate')}), smoking, drinking, foreign-spouse marriages, tertiary education and internal medicine specialists were not credible. Of the negative-control exposures, hit-and-run accidents were not associated, whereas fires ({tci(_e('fires_per_10000'))}) and recycling ({tci(_e('waste_recycling_rate'))}) were."),
("Space–time models and sensitivity analyses",
 f"All four interaction types fitted better than the principal model (ΔWAIC {dW('KH_typeIII'):,.0f} to {dW('KH_typeII'):,.0f}, type II best). Living alone and diabetes remained credible in all four types, with smaller RRs (type II {tci(S43('KH_typeII', OLD))} and {tci(S43('KH_typeII', DM))}); nutrition-label literacy was credible in types I, III and IV but not II, uptake in types I and II only (Fig. 3; Table 2), and tertiary education became credible in types II ({tci(S43('KH_typeII', 'tertiary_educated_share'))}) and IV (Table 2). In window-specific models, living alone was credible in 2011–2016 ({tci(WI(OLD, 'W1_2011-16'))}) and 2017–2024 ({tci(WI(OLD, 'W2_2017-24'))}), nutrition-label literacy in both windows, diabetes only in 2017–2024 ({tci(WI(DM, 'W2_2017-24'))}) and uptake only in 2011–2016; in the covariate-by-window interaction model, the diabetes RR was larger in 2017–2024 (ratio {N['win_int'][DM][0]:.3f}; 95% CrI {N['win_int'][DM][1]:.3f}–{N['win_int'][DM][2]:.3f}) and the living-alone RR smaller (ratio {N['win_int'][OLD][0]:.3f}; 95% CrI {N['win_int'][OLD][1]:.3f}–{N['win_int'][OLD][2]:.3f}) ({sup('windows')}). Across {ALT[OLD]['n_specs']} alternative fits listed in {sup('specs')}, living alone and diabetes were each credible in {ALT[OLD]['kept']}, nutrition-label literacy in {ALT[NUT]['kept']} and uptake in {ALT[UPT]['kept']}. These fits do not include the separate analysis omitting the share aged 80 years or older, in which diabetes was not credible ({tci(SC('s2', DM))}); that forced control had an {ci('pop80_share')}, and its variance inflation factor was {N['vif_80']:.1f} and that of living alone {N['vif_old']:.1f}, and with perturbed filled values the pooled RR for living alone was {N['rubin'][OLD]['IRR_pooled']:.3f} (95% interval {N['rubin'][OLD]['lo']:.3f}–{N['rubin'][OLD]['hi']:.3f}). E-values were {N['evalue'][OLD]['E_point']:.2f} for living alone, {N['evalue'][DM]['E_point']:.2f} for diabetes, {N['evalue'][UPT]['E_point']:.2f} for uptake and {N['evalue'][NUT]['E_point']:.2f} for nutrition-label literacy. With expected numbers from the resident population, all four remained credible and uptake was larger ({tci(N['epop'][UPT])}). For treated gastric cancer, living alone and nutrition-label literacy were not credible, whereas uptake ({tci(NCO('GCA', UPT))}) and diabetes ({tci(NCO('GCA', DM))}) were; for infectious disease, living alone ({tci(NCO('INFECT', OLD))}) and diabetes ({tci(NCO('INFECT', DM))}) had RRs below 1. Posterior predictive 95% intervals covered {100*N['ppc']['coverage95']:.1f}% of observations, and the probability integral transform histogram departed from uniformity ({sup('specs')})."),
("Associations against the expected direction",
 f"Within districts over time, uptake was positively associated ({tci(N['bw'][UPT + '__within'])}), but not between districts ({tci(N['bw'][UPT + '__between'])}); across district means its rank correlation with log ratios was negative (Spearman's ρ {N['rho_between'][UPT]:.2f}). Between and within districts, RRs were {tci(N['bw'][OLD + '__between'])} and {tci(N['bw'][OLD + '__within'])} for living alone and {tci(N['bw'][DM + '__between'])} and {tci(N['bw'][DM + '__within'])} for diabetes. Tertiary education was credible in 2017–2024 ({tci(WI('tertiary_educated_share', 'W2_2017-24'))}). Basic livelihood security receipt was positively correlated with district log ratios (ρ {N['rho_between']['basic_livelihood_rate']:.2f}) and with older adults living alone (ρ {N['rho_bl_old']:.2f}). The total fertility rate was positively correlated with district log ratios (ρ {N['rho_between']['ext__total_fertility_rate']:.2f}) and inversely with urban population share (ρ {N['rho_tfr_urban']:.2f}) ({sup('posthoc')})."),
]

DISCUSSION = [
 "After standardisation for sex and age, anaemia flagged at screening showed a largely stable divide, with excess in the south-west and south-east, many hot spots being rural counties, and deficits in the capital region. Districts with more older adults living alone and more attendees with diagnosed diabetes had more anaemia flagged; physical activity showed no credible association.",
 "### Older adults living alone",
 "The association with older adults living alone was the largest and persisted across interaction models and windows, between and within districts, but it was smaller in the space–time and window-specific models and when filled values were perturbed, indicating sensitivity to the temporal specification and to the filled early years. Individual studies suggest a pathway: living alone is associated with malnutrition risk in older people [@besoramoreno2020social], older Korean adults with anaemia more often live alone [@chueh2020high], nutritional anaemia is associated with lower nutrient intake [@park2019comparison] and nutrient deficiency is a recognised cause of anaemia in older people [@guralnik2004prevalence]. The screening statistics contain no information on diet, iron status or the cause of anaemia, so this pathway remains a hypothesis. The association was not reproduced for the two comparison outcomes, although treated outcomes also reflect access to care. Because this share was highly collinear with the share of the oldest residents, part of it may reflect very old age not removed by standardisation with an open-ended top age group. The small inverse association with nutrition-label literacy was not credible in the best-fitting interaction model and was no larger than those of negative-control exposures, so it cannot be distinguished from residual confounding [@kim2014association].",
 "### Diabetes",
 "Diagnosed diabetes was associated with anaemia between and within districts, and in window-specific models only in the later window. Anaemia is common in diabetes, especially with albuminuria or reduced kidney function [@thomas2003unrecognized], is associated with diabetes in Korean adults [@kim2021association] and rises with the stage of chronic kidney disease [@stauffer2014prevalence]; renal insufficiency, inflammation and reduced erythropoietin production contribute in older people [@stauder2018anemia]. The association was no longer credible when the share of the oldest residents was omitted and was also present, more weakly, for treated gastric cancer, so it may partly mark older and sicker attendee populations. Whether people flagged with anaemia were those with diabetes cannot be known from district data.",
 "### Other characteristics",
 "District averages of self-reported physical activity may be too coarse to show an individual effect. Smoking, expected to mask anaemia by raising haemoglobin [@nordenberg1990effect], and high-risk drinking were not associated; foreign-spouse marriages were not associated either, although thalassaemia carriage has been found among young people of multiethnic background [@lee2019increased]. Tertiary education was inversely associated in two interaction models and in the later window but not in the principal model, which leaves its role uncertain. Higher uptake was associated with more anaemia, against the expected direction; the association arose within districts over time, was shared by treated gastric cancer and was absent from two interaction models, whereas district means ranked in the expected direction. This is compatible with changes in who attends or in ascertainment as uptake rises, since adults of lower socioeconomic status attend check-ups less often [@shin2018association]. The unstable inverse associations with basic livelihood security and fertility reversed the direction of their simple correlations, possibly through collinearity with living alone or residual urban–rural differences.",
 "### Strengths and limitations",
 "The study covered every harmonised district except Sejong with consistent statistics over the whole period and standardised expected numbers for sex and age within the screened population, and the findings were tested in many sensitivity analyses. The outcome is a programme flag from a single haemoglobin measurement, without cause, severity or treatment, and its thresholds are not published, which prevents comparison with survey-defined anaemia. The cause of the nationwide fall in positivity in the middle of the period is unknown. Records are not unique people, and the attendee age structure was estimated from residents and national uptake. Associations are ecological and cannot be transferred to individuals [@morgenstern1995ecologic]. Covariates differ in quality, living alone was filled for the early years, collinearity among ageing-related characteristics was high and predictive distributions were imperfectly calibrated. No data on diet or iron status were available, and the district characteristics did not improve predictive fit over the spatial and temporal effects, so they describe rather than explain the geography. The credible negative-control exposures and small E-values show that residual district-level confounding could explain the weaker associations.",
 "### Conclusion",
 "Anaemia flagged at Korean health screening follows a stable southern geography after sex and age are taken into account. At district level it is more common where many older adults live alone and, less robustly, where many attendees have diabetes. These ecological findings generate hypotheses for individual-level studies of diet, iron status and causes of anaemia in older adults living alone, and for examining how abnormal haemoglobin results from screening are followed up.",
]

# 문장 주장 대조(결과표와 어긋나면 빌드 중단)
assert N["n_cred_hyp"] == 6 and N["n_robust"] == 4 and N["waic_main"] > N["waic_forced"] and BEST == "KH_typeII" and N["waic_nb"] < N["waic_pois"]
assert M[OLD]["IRR"] > 1 and M[DM]["IRR"] > 1 and M[NUT]["IRR"] < 1 and M[UPT]["IRR"] > 1 and all(M[v]["cred"] for v in ROB)
assert all(M[v]["cred"] and M[v]["IRR"] < 1 for v in REV) and all(N["mv"][v]["cred_frac"] < 0.75 for v in REV)
assert not any(M[v]["cred"] for v in NULLV)
assert not N["negctl"]["hit_and_run_rate"]["cred"] and N["negctl"]["fires_per_10000"]["cred"] and N["negctl"]["waste_recycling_rate"]["cred"]
assert all(dW(a) < 0 for a in KH) and all(S43(a, v)[3] for a in KH for v in (OLD, DM))
assert [a for a in KH if S43(a, NUT)[3]] == ["KH_typeI", "KH_typeIII", "KH_typeIV"] and [a for a in KH if S43(a, UPT)[3]] == ["KH_typeI", "KH_typeII"]
assert all(WI(v, w)[3] for v in (OLD, NUT) for w in ("W1_2011-16", "W2_2017-24")) and not WI(DM, "W1_2011-16")[3] and WI(DM, "W2_2017-24")[3] and WI(UPT, "W1_2011-16")[3] and not WI(UPT, "W2_2017-24")[3]
assert all(N["epop"][v][3] for v in ROB) and N["epop"][UPT][0] > M[UPT]["IRR"]
assert not NCO("GCA", OLD)[3] and not NCO("GCA", NUT)[3] and NCO("GCA", UPT)[3] and NCO("GCA", UPT)[0] > 1 and NCO("GCA", DM)[3] and NCO("GCA", DM)[0] > 1 and NCO("INFECT", OLD)[3]
assert NCO("INFECT", OLD)[0] < 1 and NCO("INFECT", DM)[0] < 1
assert N["bw"][UPT + "__within"][3] and not N["bw"][UPT + "__between"][3] and N["rho_between"][UPT] < 0
